function setupWindowExtras(){if(!$('windowFullscreen'))return;iconPaths.restore='M7 7h14v14H7V7ZM3 17V3h14';$('windowFullscreen').replaceChildren(icon('fullscreen'));$('windowFullscreen').onclick=async()=>{try{const state=await nativeAction('toggle_fullscreen');$('windowFullscreen').title=state?.fullscreen?uiText('退出全屏（F11）','Exit fullscreen (F11)'):uiText('全屏（F11）','Fullscreen (F11)');}catch(e){showError(e.message);}};$('windowMaximize').onclick=async()=>{try{const state=await nativeAction('toggle_maximize');$('windowMaximize').replaceChildren(icon(state?.maximized?'restore':'maximize'));$('windowMaximize').title=state?.maximized?uiText('还原','Restore'):uiText('最大化','Maximize');}catch(e){showError(e.message);}};}
window.addEventListener('pywebviewready',setupWindowExtras);setupWindowExtras();
document.addEventListener('keydown',e=>{if(e.key==='F11'&&window.pywebview?.api){e.preventDefault();if(!e.repeat)$('windowFullscreen').click();}});

const openOriginal=el('button','button secondary',uiText('打开原件','Open original'));openOriginal.id='openOriginal';$('downloadOriginal').before(openOriginal);openOriginal.onclick=async()=>{if(!previewFile)return;try{await api('open-file',{room:previewFile.room||current,id:previewFile.id,artifact:!!previewFile.artifact,path:previewFile.path});}catch(e){showError(e.message);}};
const panelButtons=el('div','top-panel-buttons'),terminalToggle=el('button','icon-button');terminalToggle.id='toggleBottomPanel';terminalToggle.append(icon('terminal'));terminalToggle.onclick=()=>toggleTerminalPanel().catch(e=>showError(e.message));panelButtons.append(terminalToggle);$('windowMinimize').before(panelButtons);
const finalBehavior=applyAppBehavior;let appliedHotkey;
applyAppBehavior=function(){finalBehavior();terminalToggle.hidden=!preferences.showBottomPanel;terminalToggle.title=uiText('终端与底部面板','Terminal and bottom panel');terminalToggle.setAttribute('aria-label',terminalToggle.title);if(window.pywebview?.api?.set_popout_hotkey&&new URLSearchParams(location.search).get('popout')!=='1'&&appliedHotkey!==preferences.popoutHotkey){appliedHotkey=preferences.popoutHotkey;nativeAction('set_popout_hotkey',preferences.popoutHotkey||'').catch(e=>showError(e.message));}if(loaded()&&!room.messages.length){const starters=document.querySelector('.empty-starters');if(starters)starters.hidden=!preferences.homepageSuggestions;}};
applyAppBehavior();

const settingsSelectRoom=selectRoom;selectRoom=async function(id){const old=current;await settingsSelectRoom(id);if(current===id&&old!==id)animateSurface($('chatView'));};

window.addEventListener('storage',event=>{if(event.key!=='superteam-appearance'||!event.newValue)return;try{preferences={...preferences,...JSON.parse(event.newValue)};applyAppearance();document.dispatchEvent(new CustomEvent('superteam:language'));}catch{}});
document.addEventListener('superteam:language',()=>{openOriginal.textContent=uiText('打开原件','Open original');jumpLatest.title=uiText('返回最新消息','Jump to latest');jumpLatest.setAttribute('aria-label',jumpLatest.title);lastPanel='';if(loaded())renderPanel();});

const memoryDrafts={};let memoryDetailsBusy=false;
function memoryTextEditor(key,limit){const wrap=el('div','memory-editor'),input=el('textarea');input.id='pref-'+key;input.maxLength=limit;input.rows=5;input.value=memoryDrafts[key]??preferences[key]??'';input.setAttribute('aria-label',uiText(key==='userPreferences'?'我的偏好':'自定义提示词',key==='userPreferences'?'Your preferences':'Custom instructions'));input.oninput=()=>memoryDrafts[key]=input.value;const button=settingButton('保存','Save',async()=>{await saveAppPreference(key,input.value);delete memoryDrafts[key];showError(uiText('偏好已保存，后续回复会使用。','Preferences saved for future replies.'),'success');});wrap.append(input,button);return wrap;}
async function loadMemoryDetails(){const target=$('memoryDetails');if(!target||!target.isConnected||memoryDetailsBusy)return;memoryDetailsBusy=true;try{const data=await api('memory'+(current?'?room='+encodeURIComponent(current):''));if(!target.isConnected)return;target.replaceChildren();const stateNames={idle:['尚未整理','Not run yet'],running:['正在后台整理','Summarizing in background'],completed:['已完成整理','Summary updated'],failed:['整理受阻，原记忆保留','Summary blocked; previous memory kept'],cancelled:['已停止整理','Summary stopped']};const line=el('div','memory-status');line.append(el('span','',uiText(...(stateNames[data.job.status]||stateNames.idle))+(data.job.provider?' · '+(names[data.job.provider]||data.job.provider):'')));const actions=el('div','memory-actions');actions.append(settingButton('整理当前聊天','Summarize this chat',async()=>{if(!current)return;await api('memory',{action:'refresh',room:current});await loadMemoryDetails();}));if(data.job.status==='running')actions.append(settingButton('停止','Stop',async()=>{await api('memory',{action:'stop'});await loadMemoryDetails();}));line.append(actions);target.append(line,el('p','settings-row-note',uiText('默认积累 16 条消息后才增量整理，同一聊天最多每 10 分钟自动整理一次；反馈先在本地保存。摘要是自动整理结果，不等同于事实核验。','Summaries run after 16 messages, at most once per 10 minutes per chat. Feedback is stored locally first. Summaries are not verified facts.')));
 for(const item of data.preferences){const row=el('div','memory-entry');const info=el('div','memory-entry-copy');info.append(el('h4','',item.key),el('p','',item.text),el('small','',item.manual?uiText('手动保存 · 不被后台改写','Manual · protected from background edits'):uiText('自动偏好 · 来源消息 #','Learned preference · source #')+item.source_id));const tools=el('div','memory-actions');tools.append(settingButton('编辑','Edit',async()=>{const edit=el('textarea','memory-inline-edit');edit.value=item.text;const save=settingButton('保存为手动偏好','Save as manual',async()=>{await api('memory',{action:'save',key:item.key,text:edit.value});await loadMemoryDetails();});info.replaceChildren(edit,save);}));if(item.source_room&&item.source_id)tools.append(settingButton('查看出处','Source',()=>viewMemorySource(item)));tools.append(settingButton('移除','Remove',async()=>{await api('memory',{action:'delete',key:item.key});await loadMemoryDetails();}));row.append(info,tools);target.append(row);}
 if(!data.preferences.length)target.append(el('p','settings-row-note',uiText('还没有自动偏好。你可以先填写上面的手动偏好。','No learned preferences yet. You can start with manual preferences above.')));
 if(data.summary){const box=el('div','memory-summary');box.append(el('h4','',uiText('当前聊天摘要','This chat’s summary')),el('p','',data.summary.text),el('small','',uiText('原文取样至消息 #','Sampled through message #')+data.summary.cursor));target.append(box);}
 for(const stat of data.feedback){const labels={code:['代码','Code'],research:['研究分析','Research'],writing:['写作整理','Writing'],general:['综合','General']};const row=el('div','memory-feedback-row');row.append(el('span','',(names[stat.provider]||stat.provider)+' · '+uiText(...(labels[stat.tag]||labels.general))),el('span','',uiText('支持 ','Support ')+stat.supported+' · '+uiText('不支持 ','Disagree ')+stat.opposed));target.append(row);}if(data.feedback.length)target.append(el('p','settings-row-note',uiText('反馈是偏好与满意度证据，不是客观正确率；会按任务类型帮助挑选成员，不覆盖真实工具与权限限制。','Feedback signals preference and satisfaction, not objective accuracy. It helps routing within task types without overriding tool or permission limits.')));
 }catch(e){if(target.isConnected)target.replaceChildren(el('p','settings-row-note',e.message));}finally{memoryDetailsBusy=false;}}
async function viewMemorySource(item){const data=await api('room?id='+item.source_room),message=data.messages.find(m=>m.id===item.source_id);if(!message)throw Error(uiText('原消息不可用。','The source message is unavailable.'));let dialog=$('memorySourceDialog');if(!dialog){dialog=el('dialog');dialog.id='memorySourceDialog';document.body.append(dialog);}const title=el('div','dialog-title');title.append(el('h2','',uiText('记忆出处','Memory source')+' · #'+message.id));const close=el('button','icon-button');close.append(icon('close'));close.setAttribute('aria-label',uiText('关闭','Close'));close.onclick=()=>dialog.close();title.append(close);dialog.replaceChildren(title,el('p','memory-source-meta',data.name+' · '+(names[message.author]||message.author)),el('pre','memory-source-text',message.text));dialog.showModal();}
setInterval(()=>{if(view==='settings'&&settingsCategory==='memory')loadMemoryDetails();},2500);
